dyf::Renderer.example:
#include <dyf/Renderer.h>
#include <dyf/Canvas.h>
#include <dyf/Platform/Window.h>

int main()
{
    // 준비: dy_engine을 연결한 실행 대상과 사용할 그래픽 백엔드가 필요합니다.
    dyf::Platform::Window window(960, 540, "dyf Renderer");
    if (!window.IsRunning()) return 1;

    dyf::RendererConfig config;
    config.vsync = true;
    auto renderer = dyf::Renderer::Create(window.GetHandle(), config);
    if (!renderer) return 1;

    dyf::Canvas canvas(960, 540);
    canvas.Clear({0.08f, 0.10f, 0.14f, 1.0f});
    canvas.FillRect({40, 40, 240, 120}, {0.2f, 0.7f, 1.0f, 1.0f});
    while (window.IsRunning())
    {
        dyf::Platform::Window::PollEvents();
        if (!window.IsRunning()) break;
        if (!renderer->Render(canvas)) return 1;
    }
    // 선언의 역순으로 renderer가 window보다 먼저 파괴됩니다.
}

Render.example:
#include <dyf/Renderer.h>
#include <dyf/Scene.h>
#include <dyf/Mesh.h>
#include <dyf/Camera.h>

// 준비: renderer는 유효한 창으로 Create했으며 이벤트 처리는 호출자가 합니다.
bool DrawCube(dyf::Renderer& renderer)
{
    dyf::Scene scene;
    if (!scene.Add(dyf::CreateCubeMesh())) return false;
    if (!scene.Add(dyf::DirectionalLight{})) return false;
    dyf::Camera camera;
    // 이 예제의 16:9는 창 또는 고정 출력의 실제 비율과 맞춥니다.
    if (!camera.SetPerspective(16.0f / 9.0f)) return false;
    return renderer.Render(scene, camera);
}
// 반복 렌더링에서는 scene과 camera를 루프 밖에 두어 캐시를 재사용합니다.

RenderToTexture.example:
#include <dyf/Renderer.h>
#include <dyf/Scene.h>
#include <dyf/Camera.h>
#include <dyf/RHI/Texture.h>

// 준비: scene에는 메시·광원이 있고 renderer는 유효한 창으로 생성했습니다.
// 반환한 target은 호출자가 보관하고 마지막 사용 뒤 GetDevice().DestroyTexture로 해제합니다.
dyf::RHI::TextureHandle MakePreview(dyf::Renderer& renderer,
    const dyf::Scene& scene)
{
    dyf::Camera camera;
    if (!camera.SetPerspective(1.0f)) return nullptr;
    dyf::RHI::TextureDesc desc;
    desc.width = desc.height = 512;
    desc.format = dyf::RHI::Format::R8G8B8A8_UNORM_SRGB;
    desc.usage = dyf::RHI::TextureUsage::RenderTarget
        | dyf::RHI::TextureUsage::ShaderResource;
    auto& device = renderer.GetDevice();
    auto target = device.CreateTexture(desc);
    if (!target) return nullptr;
    if (!renderer.RenderToTexture(scene, camera, target,
        dyf::RHI::ResourceState::Undefined))
    {
        device.DestroyTexture(target);
        return nullptr;
    }
    // 같은 장치의 후속 샘플링에 사용. 다음 갱신의 before는 ShaderResource입니다.
    return target;
}

CaptureEnvironment.example:
#include <dyf/Renderer.h>
#include <dyf/Scene.h>

// 준비: 유효한 창/장치의 renderer, 메시와 직접광을 등록한 scene.
// 렌더 루프 시작 전에 호출하며 셰이더 교체와 다른 렌더 호출을 동시에 하지 않습니다.
bool CaptureRoom(dyf::Renderer& renderer, const dyf::Scene& scene,
    dyf::HdrImage& radiance, dyf::HdrImage& visibility)
{
    // 한 면 256px -> 1024 x 512 선형 HDR 및 거리 파노라마.
    return renderer.CaptureEnvironment(scene, {0, 0, 1.5f}, 256,
        0.05f, 100.0f, radiance, true, &visibility);
}
// diffuse용 이미지는 별도 HdrImage에 includeEmitters=false로 한 번 더 캡처합니다.

dyf::RendererShaderDesc.example:
#include <dyf/Renderer.h>
#include <vector>
#include <cstdint>

// 준비: bytes는 선택한 RHI 백엔드용으로 컴파일하고 Renderer 정점 ABI를 지킨 바이너리입니다.
bool ReplaceMeshVertex(dyf::Renderer& renderer,
    const std::vector<uint8_t>& bytes, const char* entryPoint)
{
    if (bytes.empty() || !entryPoint || !*entryPoint) return false;
    auto shaders = renderer.GetShaders(); // 다른 단계의 사용자 교체를 유지
    shaders.meshVertex = {dyf::RHI::ShaderStage::Vertex, entryPoint,
        bytes.data(), bytes.size()};
    return renderer.SetShaders(shaders); // 입력 복사. 실제 생성은 다음 Render에서 확인
}

dyf::RendererDrawDesc.example:
#include <dyf/Renderer.h>
#include <dyf/Scene.h>
#include <dyf/Camera.h>
#include <vector>

// 준비: 기본 형상 셰이더, 표준 48바이트 정점 버퍼, Scene 인덱스와 같은 정점 순서.
// current/previous는 renderer의 장치로 만들고 GPU 사용 완료까지 유지합니다.
bool DrawDeformed(dyf::Renderer& renderer, const dyf::Scene& scene,
    const dyf::Camera& camera, uint32_t entityIndex,
    dyf::RHI::BufferHandle current, dyf::RHI::BufferHandle previous,
    const dyf::Math::Bounds3& bounds, uint64_t revision)
{
    if (entityIndex >= scene.GetEntityCount() || !current
        || !bounds.valid || revision == 0) return false;
    std::vector<dyf::RendererDrawDesc> draws(scene.GetEntityCount());
    for (auto& draw : draws) draw.stockGeometry = true;
    auto& draw = draws[entityIndex];
    draw.vertexBuffer = current;
    draw.previousVertexBuffer = previous;
    draw.localBounds = bounds;
    draw.hasLocalBounds = true;
    draw.deformationHistoryValid = previous != nullptr;
    draw.geometryRevision = revision; // 형상 내용이 바뀔 때마다 변경
    return renderer.Render(scene, camera, draws);
}

dyf::RendererConfig.example:
#include <dyf/Renderer.h>

// 준비: Create가 성공한 renderer입니다. 실제 적용은 다음 Render에서 확인합니다.
bool RequestFixedHdrOutput(dyf::Renderer& renderer)
{
    auto config = renderer.GetConfig();
    config.renderWidth = 1280;
    config.renderHeight = 720;
    config.enableHdrRendering = true;
    config.hdrRenderScale = 1.5f; // 장면 1920 x 1080 -> 출력 1280 x 720
    config.exposure = 1.2f;
    return renderer.SetConfig(config);
}
// 다음 Render가 성공한 뒤 GetAppliedConfig와 GetLastRenderStatistics로 확인합니다.

dyf::LightingConfig.example:
#include <dyf/Renderer.h>

bool ConfigureLighting(dyf::Renderer& renderer)
{
    auto lighting = renderer.GetLighting(); // const 참조가 아닌 값 복사
    lighting.enabled = true;
    lighting.direct = true;
    lighting.shadows = true;
    lighting.shadowQuality = dyf::ShadowQuality::Medium;
    lighting.shadowDistance = 60.0f; // 장면과 같은 월드 단위
    lighting.maxDirectionalShadowLights = 1;
    lighting.maxPointShadowLights = 4;
    lighting.maxSpotShadowLights = 2;
    return renderer.SetLighting(lighting);
}
// 이후 renderer.Render(scene, camera)의 bool 결과도 확인합니다.

dyf::EnvironmentDesc.example:
#include <dyf/Renderer.h>
#include <dyf/Image.h>
#include <dyf/Extends/AdvancedRendering.h>
#include <string>

// 렌더러 초기화 시 한 번 호출합니다.
bool ConfigureSky(dyf::Renderer& renderer, const std::string& hdrPath)
{
    dyf::HdrImage sky;
    if (!dyf::LoadHdrImage(hdrPath, sky)) return false;
    auto config = renderer.GetConfig();
    config.enableHdrRendering = true;
    config.advanced.enabled = true;
    config.lighting.enabled = true;
    config.lighting.environment.radiance = sky;
    config.lighting.environment.intensity = 0.8f;
    config.lighting.environment.rotationRadians = 0.5f;
    config.lighting.environment.background = true;
    if (!renderer.SetConfig(config)) return false;
    if (!renderer.AddExtension(dyf::CreateAdvancedRenderingModule(
            dyf::AdvancedRenderModule::SurfaceLighting))) return false;
    return renderer.AddExtension(dyf::CreateAdvancedRenderingModule(
        dyf::AdvancedRenderModule::EnvironmentLighting));
}
// 이후 Render(scene, camera)의 실패 여부도 확인합니다.

dyf::Scene.example:
#include "dyf/Scene.h"
#include "dyf/Camera.h"

int main()
{
    dyf::Scene scene;
    dyf::Camera camera;

    auto original = scene.Add(dyf::CreateCubeMesh());
    if (!original || !original.SetPosition({-1, 0, 0})) return 1;

    auto world = dyf::Math::float4x4::Identity();
    world.m[12] = 1.0f;
    auto instance = scene.AddInstance(original, world);
    if (!instance) return 1;

    auto light = scene.Add(dyf::DirectionalLight{});
    if (!light) return 1;
    if (!camera.LookAt({0, -5, 3})) return 1;
    if (!camera.SetPerspective(16.0f / 9.0f)) return 1;

    // 이 시점에 scene과 camera를 Renderer::Render에 전달할 수 있습니다.
    return 0;
}

