dyf::MaterialDesc.example:
#include <dyf/Material.h>
#include <dyf/Mesh.h>
#include <dyf/Scene.h>

int main()
{
    dyf::MaterialDesc material;
    material.baseColor = {0.7f, 0.9f, 0.6f, 1.0f};
    material.roughnessFactor = 0.65f;
    // 두 픽셀 중 하나의 알파가 0인 색 텍스처를 준비한다.
    material.baseColorTexture = dyf::Image(2, 1,
        {255, 255, 255, 255, 255, 255, 255, 0}, dyf::ColorSpace::Srgb);
    if (!material.baseColorTexture.IsValid()) return 1;
    material.alphaMode = dyf::MaterialAlphaMode::Mask;
    material.alphaCutoff = 0.5f;
    material.doubleSided = true;

    dyf::Scene scene;
    auto object = scene.Add(dyf::CreateCubeMesh(), material);
    if (!object) return 2;

    auto edited = object.GetMaterial();
    edited.roughnessFactor = 0.25f;
    if (!object.SetMaterial(edited)) return 3;
    // CPU 장면 등록과 갱신까지의 예제다. 표시는 준비된 Renderer로 수행한다.
    return 0;
}

dyf::Camera.example:
#include "dyf/Camera.h"
#include <cstdint>

bool UpdateCamera(dyf::Camera& camera, uint32_t width, uint32_t height)
{
    if (width == 0 || height == 0) return false;
    if (!camera.LookAt({0, -5, 3}, {0, 0, 0}, {0, 0, 1})) return false;
    const float aspect = static_cast<float>(width) / static_cast<float>(height);
    return camera.SetPerspective(aspect, 1.04719755f, 0.1f, 100.0f);
}

