dyf::Canvas.example:
#include <dyf.h>
#include <cstdio>
#include <exception>

int main()
{
    try
    {
        dyf::Platform::Window window(640, 480, "Canvas 예제");
        if (!window.GetHandle()) return 1;
        auto renderer = dyf::Renderer::Create(window.GetHandle());
        if (!renderer) return 1;

        while (window.IsRunning())
        {
            window.PollEvents();
            if (!window.IsRunning()) break;
            const auto size = window.GetFramebufferSize();
            if (size.width <= 0 || size.height <= 0) continue;
            dyf::Canvas canvas(static_cast<uint32_t>(size.width),
                               static_cast<uint32_t>(size.height));
            if (!canvas.IsValid()) return 1;
            canvas.Clear({0.04f, 0.06f, 0.10f, 1});
            if (!canvas.SetViewport({20, 20, 280, 180})) return 1;
            canvas.SetClipRect({0, 0, 260, 160});
            canvas.FillRect({10, 10, 220, 100}, {0.1f, 0.65f, 0.95f, 1});
            canvas.Line({10, 130}, {240, 130}, {1, 1, 1, 1}, 2);
            if (!renderer->Render(canvas)) return 1;
        }
        return 0;
    }
    catch (const std::exception& error)
    {
        std::fprintf(stderr, "%s\n", error.what());
        return 1;
    }
}

