// 추가 예제: 생성이 성공한 창과 렌더러를 빌려 사용합니다.
#include <dyf.h>

int RunCanvasCursorExample(dyf::Platform::Window& window,
                           dyf::Renderer& renderer)
{
    window.SetCursorMode(dyf::Platform::CursorMode::Normal);
    while (window.IsRunning())
    {
        dyf::Platform::Window::PollEvents();
        if (!window.IsRunning()) break;
        const auto content = window.GetSize();
        const auto framebuffer = window.GetFramebufferSize();
        if (window.IsMinimized() || content.width <= 0 || content.height <= 0
            || framebuffer.width <= 0 || framebuffer.height <= 0) continue;

        dyf::Canvas canvas(static_cast<uint32_t>(framebuffer.width),
                           static_cast<uint32_t>(framebuffer.height));
        if (!canvas.IsValid()) return 1;
        canvas.Clear();
        const dyf::Rectangle viewport{40, 30, 200, 120};
        if (!canvas.SetViewport(viewport)) return 1;
        const auto cursor = window.GetInput().GetCursorPosition();
        const dyf::Math::float2 local{
            static_cast<float>(cursor.x * framebuffer.width / content.width - viewport.x),
            static_cast<float>(cursor.y * framebuffer.height / content.height - viewport.y)};
        canvas.Point(local, {1, 1, 0, 1}, 4);
        if (!renderer.Render(canvas)) return 1;
    }
    return 0;
}

