// fontPath에는 사용 권한이 있고 필요한 문자를 포함하는 로컬 글꼴 파일 경로를 전달합니다.
// renderer는 살아 있는 창으로 생성한 객체이며, windowWidth·windowHeight는 출력 픽셀 크기입니다.
bool RenderLabel(dyf::Renderer& renderer, const std::string& fontPath,
                 uint32_t windowWidth, uint32_t windowHeight)
{
    auto font = dyf::Font::Load(fontPath, 24);
    if (!font) return false;
    dyf::Canvas label(windowWidth, windowHeight);
    if (!label.IsValid()) return false;
    label.Clear({0.04f, 0.06f, 0.10f, 1});
    if (!label.Text(*font, "화면 안내\n둘째 줄", {20, 20})) return false;
    return renderer.Render(label);
}

