dyf::FontGlyph.example:
#include <dyf/Font.h>
#include <dyf/Image.h>
#include <dyf/Types.h>
#include <string>

// localFontPath에는 사용 권한이 있고 '가'를 포함하는 로컬 글꼴 파일 경로를 전달합니다.
// atlas도 출력하여 아래 UV와 같은 픽셀 스냅샷을 유지합니다.
bool LocateGlyph(const std::string& localFontPath, dyf::Rectangle& destination,
                 dyf::Rectangle& uv, dyf::Image& atlas)
{
    auto font = dyf::Font::Load(localFontPath, 24);
    if (!font) return false;
    dyf::FontGlyph glyph;
    if (!font->GetGlyph(0xAC00, glyph)) return false;
    atlas = font->GetAtlas();
    if (!atlas.IsValid()) return false;
    const float penX = 20;
    const float baselineY = 20 + font->GetAscent();
    destination = {penX + glyph.offsetX, baselineY + glyph.offsetY,
                   static_cast<float>(glyph.width), static_cast<float>(glyph.height)};
    const float atlasWidth = static_cast<float>(atlas.GetWidth());
    const float atlasHeight = static_cast<float>(atlas.GetHeight());
    uv = {glyph.x / atlasWidth, glyph.y / atlasHeight,
          glyph.width / atlasWidth, glyph.height / atlasHeight};
    return true;
}

