bool AddPasses(dyf::RenderStage stage, dyf::RenderFrame& frame,
               dyf::RHI::RenderGraph& graph) override
{
    if(stage != dyf::RenderStage::PostProcess) return true;
    if(frame.outputWritten) return true;
    // 실제 출력 패스와 outputWritten 처리는 RenderExtension 예제에 있습니다.
    return frame.output.texture && frame.output.resource.IsValid();
}

