dyf::RenderRequirements.example:
// 표면 데이터 없이 준비된 메시 목록만 사용하는 확장의 요구 선언입니다.
dyf::RenderRequirements GetRequirements(const dyf::Renderer&) const override
{
    dyf::RenderRequirements requirements;
    requirements.needsGeometry = true;
    return requirements;
}
