dyf::BuildMeshLods.example:
#include <dyf/Mesh.h>
#include <dyf/Scene.h>
#include <cstdio>

int main()
{
    constexpr uint32_t cells = 16;
    constexpr uint32_t stride = cells + 1;
    dyf::MeshData mesh;
    // 289개 정점과 1536개 인덱스를 가진 +Z 방향 평면을 준비한다.
    for (uint32_t y = 0; y <= cells; ++y)
        for (uint32_t x = 0; x <= cells; ++x)
        {
            const float u = static_cast<float>(x) / cells;
            const float v = static_cast<float>(y) / cells;
            dyf::Vertex vertex{};
            vertex.position = {u, v, 0.0f};
            vertex.normal = {0.0f, 0.0f, 1.0f};
            vertex.uv = {u, v};
            mesh.vertices.push_back(vertex);
        }
    for (uint32_t y = 0; y < cells; ++y)
        for (uint32_t x = 0; x < cells; ++x)
        {
            const uint32_t a = y * stride + x;
            mesh.indices.insert(mesh.indices.end(),
                {a, a + 1, a + stride, a + 1, a + stride + 1, a + stride});
        }

    mesh.lods = dyf::BuildMeshLods(mesh, 3);
    if (mesh.lods.empty())
        std::puts("추가 LOD를 만들 수 없어 원본 메시 사용");
    else
        std::printf("추가 LOD 수: %zu\n", mesh.lods.size());

    dyf::Scene scene;
    auto object = scene.Add(mesh);
    if (!object) return 1;
    return 0;
}

