#include "dyf/Renderer.h"
#include "dyf/Scene.h"
#include "dyf/Camera.h"
#include "dyf/Extends/AdvancedRendering.h"

// window와 scene/camera는 호출자가 준비해 함수 종료까지 유지합니다.
// 이 예제는 새 렌더러에 SurfaceLighting을 한 번만 등록합니다.
bool ShowSurfaceNormals(const void* window, const dyf::Scene& scene,
                        const dyf::Camera& camera)
{
    auto renderer = dyf::Renderer::Create(window);
    if (!renderer) return false;
    if (!renderer->AddExtension(dyf::CreateAdvancedRenderingModule(
            dyf::AdvancedRenderModule::SurfaceLighting))) return false;

    auto config = renderer->GetConfig();
    config.enableHdrRendering = true;
    config.advanced.enabled = true;
    config.debugWireframe = false;
    config.debugLodColor = false;
    config.advanced.surfaceDebugView = dyf::SurfaceDebugView::Normal;
    if (!renderer->SetConfig(config)) return false;
    if (!renderer->Render(scene, camera)) return false;
    return renderer->GetAppliedConfig().advanced.surfaceDebugView
        == dyf::SurfaceDebugView::Normal;
}
// 정상 모드로 돌릴 때는 같은 렌더러에서 None을 SetConfig한 뒤 다시 Render합니다.
// true는 요청 적용 확인이며, 프레임 생략 가능성이 있어 표시 결과도 확인합니다.

