#include <memory>

// 유효한 기본 메시/재질, 광원, 카메라를 갖춘 scene을 넘깁니다.
// AdvancedRendering 프리셋은 SurfaceLighting/EnvironmentLighting 등 6개를 포함합니다.
bool RenderAdvancedScene(const void* window, const dyf::Scene& scene,
                         const dyf::Camera& camera)
{
    auto renderer = dyf::Renderer::Create(window);
    if (!renderer) return false;
    if (!renderer->AddExtension(std::make_unique<dyf::AdvancedRendering>()))
        return false; // 같은 개별 모듈을 다시 등록하지 않습니다.

    auto config = renderer->GetConfig();
    config.enableHdrRendering = true;
    config.exposure = 1.0f; // EV가 아니라 배율입니다.
    config.advanced.enabled = true;
    config.advanced.temporalAA = true;
    config.advanced.autoExposure = true;
    config.advanced.exposureKey = 0.18f;
    config.advanced.historyWeight = 0.9f;
    config.advanced.surfaceDebugView = dyf::SurfaceDebugView::None;
    if (!renderer->SetConfig(config)) return false;
    if (!renderer->Render(scene, camera)) return false;
    return renderer->GetAppliedConfig().enableHdrRendering
        && renderer->GetAppliedConfig().advanced.enabled;
}
// 실제 앱은 renderer를 유지해 다음 프레임도 Render합니다.
// 첫 프레임만으로 TAA 누적/노출 적응을 판정하지 않으며, 화면 결과도 확인합니다.

dyf::PostProcessConfig.example:
#include "dyf/Renderer.h"
#include "dyf/Scene.h"
#include "dyf/Camera.h"

// 이 예제는 기본 HDR 톤 매핑을 사용하므로 확장 모듈 등록이 필요 없습니다.
bool RenderGradedScene(const void* window, const dyf::Scene& scene,
                       const dyf::Camera& camera)
{
    auto renderer = dyf::Renderer::Create(window);
    if (!renderer) return false;
    auto config = renderer->GetConfig();
    config.enableHdrRendering = true;
    config.postProcess.temperature = 0.1f; // 켈빈이 아닌 상대값
    config.postProcess.tint = 0.0f;
    config.postProcess.contrast = 1.05f;
    config.postProcess.saturation = 1.1f;
    config.postProcess.sharpening = true;
    config.postProcess.sharpness = 0.2f;
    if (!renderer->SetConfig(config)) return false;
    if (!renderer->Render(scene, camera)) return false;
    return renderer->GetAppliedConfig().postProcess.sharpening;
}
// 실제 앱에서는 renderer를 보존하고, 보정값을 바꿀 때만 SetConfig합니다.
// true에는 프레임 생략도 포함되므로 출력된 장면 색과 선명도도 확인합니다.

dyf::EntityID.example:
#include "dyf/Scene.h"

bool SelectFirst(dyf::Scene& scene, dyf::EntityID& selected)
{
    selected = dyf::EntityID::Invalid;
    if (scene.GetEntityCount() == 0) return false;
    selected = static_cast<dyf::EntityID>(0u);
    return static_cast<bool>(scene.GetEntity(selected));
}

dyf::ToIndex.example:
#include "dyf/Scene.h"

static_assert(dyf::ToIndex(dyf::EntityID::Invalid) == 0xFFFFFFFFu);

std::shared_ptr<const dyf::MeshData> FindMesh(const dyf::Scene& scene, dyf::EntityID id)
{
    if (!dyf::IsValid(id) || dyf::ToIndex(id) >= scene.GetEntityCount()) return {};
    const auto meshID = scene.GetEntityMesh(id);
    return scene.Meshes()[dyf::ToIndex(meshID)];
}

dyf::IsValid.example:
#include "dyf/Scene.h"

static_assert(!dyf::IsValid(dyf::EntityID::Invalid));
static_assert(dyf::IsValid(dyf::EntityID{}));  // 값은 0이며 등록 여부는 모릅니다.

bool HasEntity(const dyf::Scene& scene, dyf::EntityID id)
{
    return dyf::IsValid(id) && dyf::ToIndex(id) < scene.GetEntityCount();
}

dyf::DecodeUtf8.example:
#include <dyf/Utf8.h>
#include <cassert>
#include <cstddef>
#include <cstdint>
#include <string_view>

int main()
{
    const std::string_view text = "A\xEA\xB0\x80"; // UTF-8의 'A가'입니다.
    size_t at = 0;
    size_t count = 0;
    while (at < text.size())
    {
        const uint32_t codepoint = dyf::DecodeUtf8(text, at);
        if (count == 0) assert(codepoint == 'A');
        if (count == 1) assert(codepoint == 0xAC00);
        ++count;
    }
    assert(count == 2 && at == text.size());

    const std::string_view broken = "\xE1\x80" "A";
    at = 0;
    const auto replacement = dyf::DecodeUtf8(broken, at);
    assert(replacement == 0xFFFD && at == 2);
    const auto recovered = dyf::DecodeUtf8(broken, at);
    assert(recovered == 'A' && at == 3);
    const size_t end = at;
    const auto afterEnd = dyf::DecodeUtf8(broken, at);
    assert(afterEnd == 0xFFFD && at == end);
    return 0;
}

dyf::ColorSpace.example:
#include <dyf/Image.h>

bool ReadNormalMap(dyf::Image& normal)
{
    if (!dyf::LoadImage("assets/normal.png", normal)) return false;
    // 노멀맵 채널은 색상 감마가 아닌 수치 데이터다.
    normal.SetColorSpace(dyf::ColorSpace::Linear);
    return normal.GetColorSpace() == dyf::ColorSpace::Linear;
}

