dyf::HdrImage.example:
#include <dyf/Image.h>
#include <cassert>
#include <cmath>

int main()
{
    dyf::HdrImage image(1, 1, {4.0f, 2.0f, 0.5f, 1.0f});
    if (!image.IsValid()) return 1;
    for (float value : image.GetPixels())
        if (!std::isfinite(value) || value < 0.0f) return 1;

    dyf::HdrImage retained = image;
    image = dyf::HdrImage{};
    assert(retained.GetPixels()[0] == 4.0f);
}

dyf::LoadHdrImage.example:
#include <dyf/Image.h>
#include <cstdio>

bool ReadEnvironment(dyf::HdrImage& environment)
{
    // 파일이 없거나 HDR 형식이 아니면 기존 environment를 유지한다.
    if (!dyf::LoadHdrImage("assets/studio.hdr", environment)) return false;
    std::printf("HDR: %u x %u, first R = %g\n",
                environment.GetWidth(), environment.GetHeight(),
                static_cast<double>(environment.GetPixels()[0]));
    return true;
}

dyf::GetImageDimensions.example:
#include <dyf/Image.h>
#include <cstdio>

bool InspectAndRead(const std::string& path, dyf::Image& image)
{
    uint32_t width = 0, height = 0;
    if (!dyf::GetImageDimensions(path, width, height)) return false;
    const uint64_t rgbaBytes = uint64_t(width) * height * 4u;
    std::printf("%u x %u, RGBA8 = %llu bytes\n", width, height,
                static_cast<unsigned long long>(rgbaBytes));
    // 메타데이터를 읽었어도 전체 디코딩은 별도로 실패할 수 있다.
    return dyf::LoadImage(path, image);
}
